from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import combinations, product
import heapq


def dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {}
    domains = []
    for name in names:
        eligible = [row for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        rows[name] = {row["version"]: row for row in eligible}
        domains.append([None] + [row["version"] for row in eligible])

    roots = data.get("roots", {})
    best = None
    best_vector = None
    for values in product(*domains):
        chosen = {name: version for name, version in zip(names, values)
                  if version is not None}
        if any(name not in chosen or not bounds[0] <= chosen[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        reachable = set()
        edges = {}
        pending = list(roots)
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            if name not in chosen:
                valid = False
                break
            reachable.add(name)
            row = rows[name][chosen[name]]
            children = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                version = chosen.get(target)
                if version is None or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                children.append(target)
                pending.append(target)
            edges[name] = children
        if not valid or reachable != set(chosen):
            continue

        active, finished = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(child) for child in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in edges):
            continue
        vector = tuple(chosen.get(name, -1) for name in names)
        if (best_vector is None or
                (vector > best_vector if preference == "maximum"
                 else vector < best_vector)):
            best, best_vector = chosen, vector

    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        rank = (event.get("revision", 0), pos)
        if event_id not in winners or rank > winners[event_id][0]:
            winners[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    half_up = data["rounding"] == "half_up"

    def rounded(numerator):
        return ((numerator + 5000) // 10000 if half_up
                else numerator // 10000)

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def quota_intervals(data):
    k = data["k"]
    blocked = set(data.get("blocked", []))
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    by_id = {job["id"]: job for job in jobs}
    mandatory = set(data.get("mandatory", []))
    if not mandatory.issubset(by_id) or len(mandatory) > k:
        return {"error": "impossible"}
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        valid = True
        for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                valid = False
                break
        if not valid:
            continue

        selected = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_ids, best_value = selected, value

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def temporal_routes(data):
    required = data.get("required", [])
    bit_for = {node: sum(1 << i for i, required_node in enumerate(required)
                         if node == required_node)
               for node in range(data["n"])}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit_for[source]
    initial = (source, initial_mask, data["coupons"])
    start = data["start"]
    distances = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, coupons - 1))
            for duration, remaining in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_state = (nxt, mask | bit_for[nxt], remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_state[1], remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda data: dependency_solver(data, "maximum", "ascending"),
    "component_02": lambda data: dependency_solver(data, "minimum", "ascending"),
    "component_03": lambda data: dependency_solver(data, "maximum", "descending"),
    "component_04": lambda data: dependency_solver(data, "minimum", "descending"),
    "component_05": lambda data: dependency_solver(data, "maximum", "ascending"),
    "component_06": ledger,
    "component_07": quota_intervals,
    "component_08": temporal_routes,
}
